File:
plugins {
    id 'java'
}

group = 'com.example'
version = '1.0-SNAPSHOT'

// Java-Version (kann bei Bedarf auf 11 oder 8 angepasst werden)
sourceCompatibility = JavaVersion.VERSION_17
targetCompatibility = JavaVersion.VERSION_17

repositories {
    mavenCentral()
}

dependencies {
    // 1. EXCEL (Apache POI für .xlsx und .xls)
    implementation 'org.apache.poi:poi:5.2.5'
    implementation 'org.apache.poi:poi-ooxml:5.2.5'

    // Log4j-Binding (wird von Apache POI für Logging benötigt)
    implementation 'org.apache.logging.log4j:log4j-api:2.22.1'
    implementation 'org.apache.logging.log4j:log4j-core:2.22.1'

    // 2. CSV (Apache Commons CSV)
    implementation 'org.apache.commons:commons-csv:1.10.0'

    // 3. PDF (OpenPDF - Open-Source-Alternative zu iText)
    implementation 'com.github.librepdf:openpdf:1.3.30'

    // Testing (JUnit 5)
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.1'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

test {
    useJUnitPlatform()
}

plugins {
    id 'java'
    id 'org.springframework.boot' version '3.2.5'
    id 'io.spring.dependency-management' version '1.1.4'
}

group = 'com.example'
version = '1.0.0'

java {
    sourceCompatibility = JavaVersion.VERSION_17
}

repositories {
    mavenCentral()
}

dependencies {
    // Enthält den WebClient und die reaktive Engine (Reactor Netty)
    implementation 'org.springframework.boot:spring-boot-starter-webflux'

    // Für JSON-Serialisierung/Deserialisierung
    implementation 'org.springframework.boot:spring-boot-starter-json'

    // Lombok (optional, spart Boilerplate-Code)
    compileOnly 'org.projectlombok:lombok'
    annotationProcessor 'org.projectlombok:lombok'

    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testImplementation 'io.projectreactor:reactor-test'
}

test {
    useJUnitPlatform()
}

plugins {
    id 'java'
    id 'application'
    // Erstellt eine ausführbare "Fat-JAR" mit allen Abhängigkeiten
    id 'com.github.johnrengelman.shadow' version '8.1.1'
}

group = 'de.deinname.batch'
version = '1.0.0'

// Java 17 oder höher wird für moderne Bibliotheken empfohlen
java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

repositories {
    mavenCentral()
}

dependencies {
    // 1. CSV Import
    implementation 'org.apache.commons:commons-csv:1.10.0'

    // 2. Excel Generierung (XLSX)
    implementation 'org.apache.poi:poi-ooxml:5.2.5'

    // 3. PDF Export (Open-Source & lizenzfrei, Fork von iText)
    implementation 'com.github.librepdf:openpdf:1.3.30'

    // 4. Logging (Essentiell für Batch-Tools)
    implementation 'org.slf4j:slf4j-api:2.0.9'
    implementation 'ch.qos.logback:logback-classic:1.4.11'

    // Hilfsmittel: Lombok (spart Getter/Setter/Boilerplate)
    compileOnly 'org.projectlombok:lombok:1.18.30'
    annotationProcessor 'org.projectlombok:lombok:1.18.30'

    // Testing
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.0'
}

// Definition der Main-Klasse für das Application- & Shadow-Plugin
application {
    mainClass = 'de.deinname.batch.MainApp'
}

tasks.named('test') {
    useJUnitPlatform()
}

// Konfiguration für das Shadow-Jar (Fat-JAR)
shadowJar {
    archiveBaseName.set('batch-import-tool')
    archiveClassifier.set('all')
    archiveVersion.set(project.version)
}

plugins {
    id 'java'
}

group = 'de.deinprojekt'
version = '1.0-SNAPSHOT'

repositories {
    mavenCentral()
}

java {
    toolchain {
        // Java 17 oder höher wird empfohlen
        languageVersion = JavaLanguageVersion.of(17)
    }
}

dependencies {
    // --- JSON & XML Parsing (Jackson) ---
    // Basis für Datenbindung (JSON -> Java-Objekt)
    implementation 'com.fasterxml.jackson.core:jackson-databind:2.17.0'
    // Ermöglicht Jackson das Parsen von XML (XML -> Java-Objekt)
    implementation 'com.fasterxml.jackson.dataformat:jackson-dataformat-xml:2.17.0'

    // --- Komfort & Boilerplate-Reduzierung ---
    // Lombok für @Data, @Builder, etc. (vereinfacht die Java-Objekte)
    compileOnly 'org.projectlombok:lombok:1.18.32'
    annotationProcessor 'org.projectlombok:lombok:1.18.32'

    // --- Testing ---
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.2'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
}

plugins {
    id 'java'
    id 'org.springframework.boot' version '3.2.4' // Aktuelle Spring Boot Version
    id 'io.spring.dependency-management' version '1.1.4'
}

group = 'com.example'
version = '0.0.1-SNAPSHOT'

// Java 17 oder 21 wird für Spring Boot 3 empfohlen
java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

configurations {
    compileOnly {
        extendsFrom annotationProcessor
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // WebFlux enthält den reaktiven WebClient (besser als RestTemplate für viele APIs)
    implementation 'org.springframework.boot:spring-boot-starter-webflux'

    // Resilience4j für fortgeschrittene Retries, Rate Limiter und Circuit Breaker
    implementation 'io.github.resilience4j:resilience4j-spring-boot3:2.2.0'
    implementation 'org.springframework.boot:spring-boot-starter-aop' // Erforderlich für Resilience4j-Annotationen

    // Lombok, um Boilerplate-Code (Getter/Setter für JSON-DTOs) zu minimieren
    compileOnly 'org.projectlombok:lombok'
    annotationProcessor 'org.projectlombok:lombok'

    // Testing
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testImplementation 'io.projectreactor:reactor-test' // Für WebClient-Tests
}

tasks.named('test') {
    useJUnitPlatform()
}

plugins {
    // Aktiviert die Java-Unterstützung
    id 'java'
    // Ermöglicht das einfache Starten und Paketieren als ausführbare Anwendung
    id 'application'
}

group = 'de.exporttool'
version = '1.0.0'

// Setzt Java-Kompatibilität auf Version 17 (LTS) oder höher empfohlen
sourceCompatibility = JavaVersion.VERSION_17
targetCompatibility = JavaVersion.VERSION_17

repositories {
    mavenCentral()
}

dependencies {
    // 1. EXCEL: Apache POI für moderne .xlsx-Dateien
    implementation 'org.apache.poi:poi-ooxml:5.2.5'

    // Log4j-API-Umleitung (wird von Apache POI benötigt, um Warnungen zu vermeiden)
    implementation 'org.apache.logging.log4j:log4j-to-slf4j:2.22.1'

    // 2. CSV: Apache Commons CSV (hervorragend für Sonderzeichen/Encodings)
    implementation 'org.apache.commons:commons-csv:1.10.0'

    // 3. PDF: OpenPDF (Open-Source-Alternative zu iText, ideal für PDFs mit Tabellen/Text)
    implementation 'com.github.librepdf:openpdf:1.3.40'

    // Logging (SLF4J mit einfacher Konsolen-Ausgabe)
    implementation 'org.slf4j:slf4j-api:2.0.12'
    implementation 'org.slf4j:slf4j-simple:2.0.12'

    // Testing (JUnit 5)
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.2'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

// Erzwingt UTF-8-Encoding beim Kompilieren (wichtig für Sonderzeichen im Code)
tasks.withType(JavaCompile) {
    options.encoding = 'UTF-8'
}

// Erzwingt UTF-8-Encoding bei der Testausführung
tasks.withType(Test) {
    useJUnitPlatform()
    systemProperty "file.encoding", "UTF-8"
}

// Konfiguration für das 'application'-Plugin
application {
    // Definiert die Hauptklasse deiner Anwendung (hier anpassen)
    mainClass = 'de.exporttool.Main'
}

// Erstellt ein "Fat-JAR" (eine einzige ausführbare JAR-Datei, die alle Abhängigkeiten enthält)
tasks.register('uberJar', Jar) {
    archiveClassifier = 'all'
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE

    manifest {
        attributes 'Main-Class': application.mainClass
    }

    from {
        configurations.runtimeClasspath.collect { it.isDirectory() ? it : zipTree(it) }
    }
    with jar
}

plugins {
    id 'java'
    id 'application' // Ermöglicht das direkte Starten der App
}

group = 'com.example'
version = '1.0-SNAPSHOT'

repositories {
    mavenCentral()
}

dependencies {
    // 1. Apache HttpClient 5 (Unterstützt Pooling, Retries, Timeouts, Proxy)
    implementation 'org.apache.httpcomponents.client5:httpclient5:5.3.1'

    // 2. Jackson für JSON-Verarbeitung (Parsing & Serialisierung)
    implementation 'com.fasterxml.jackson.core:jackson-databind:2.17.0'

    // 3. Logging (Wichtig für HTTP-Debugging und HttpClient-Logs)
    implementation 'ch.qos.logback:logback-classic:1.5.3'

    // JUnit 5 für Tests
    testImplementation platform('org.junit:junit-bom:5.10.2')
    testImplementation 'org.junit.jupiter:junit-jupiter'
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17) // Empfohlene Java-Version
    }
}

application {
    // Hauptklasse zum Starten der Anwendung
    mainClass = 'com.example.HttpClientApp'
}

test {
    useJUnitPlatform()
}
